package com.andye.warmod.warhead;import java.util.*;public final class StrategicMissilePayloadRegistry{private static final Map<UUID,StrategicMissilePayload> ACTIVE=new HashMap<>();private StrategicMissilePayloadRegistry(){}public static synchronized void put(UUID id,StrategicMissilePayload p){ACTIVE.put(id,p);}public static synchronized StrategicMissilePayload get(UUID id,WarheadPayloadType fallback){return ACTIVE.getOrDefault(id,new StrategicMissilePayload(fallback,WarheadDeliveryMode.SINGLE));}public static synchronized void remove(UUID id){ACTIVE.remove(id);}public static synchronized void clear(){ACTIVE.clear();}}
